--- a/services/slo-enforcer/ordering.go
+++ b/services/slo-enforcer/ordering.go
@@ -12,7 +12,23 @@
-// previous comparator: compared only fallback_priority and region
+// new comparator: region_affinity > fallback_priority > enqueue_seq_id (monotonic, stable)
+func compare(a, b *EnqueueEntry) int {
+  if a.RegionAffinity != b.RegionAffinity {
+    return regionPriority(a.RegionAffinity) - regionPriority(b.RegionAffinity)
+  }
+  if a.FallbackPriority != b.FallbackPriority {
+    return a.FallbackPriority - b.FallbackPriority
+  }
+  // monotonic sequence id prevents reordering for concurrently reconciled entries
+  if a.EnqueueSeqID < b.EnqueueSeqID {
+    return -1
+  } else if a.EnqueueSeqID > b.EnqueueSeqID {
+    return 1
+  }
+  return 0
+}
